import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

function Register() {

    const navigate = useNavigate();

    const [name, setName] = useState('');
    const [family, setFamily] = useState('');
    const [email, setEmail] = useState('');
    const [phone, setPhone] = useState('');
    const [password, setPassword] = useState('');
    const [image, setImage] = useState(null);

    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        const data = new FormData();
        data.append('name', name);
        data.append('family', family);
        data.append('email', email);
        data.append('phone', phone);
        data.append('password', password);

        if (image) {
            data.append('img', image);
        }

        try {
            const response = await fetch('http://localhost:8000/api/register', {
                method: 'POST',
                body: data
            });

            if (!response.ok) {
                throw new Error('خطا در ثبت نام');
            }

            const result = await response.json();
            console.log('پاسخ سرور:', result);

            navigate('/login');

        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <main className="container mt-4 pt-5">
            <div className="container-fluid mt-5">
                <div className="row">
                    <div className="col-xl-5 col-md-12">
                        <div className="d-flex justify-content-center align-items-center">
                            <div className="register-card shadow-lg p-5 item-back rounded-5 boder">
                                <h4 className="mb-4 text-color text-center">Register</h4>

                                <form onSubmit={handleSubmit} encType="multipart/form-data">

                                    <div className="form-floating mb-3">
                                        <input
                                            type="text"
                                            className="form-control"
                                            placeholder="First Name"
                                            value={name}
                                            onChange={(e) => setName(e.target.value)}
                                            required
                                        />
                                        <label>First Name</label>
                                    </div>

                                    <div className="form-floating mb-3">
                                        <input
                                            type="text"
                                            className="form-control"
                                            placeholder="Last Name"
                                            value={family}
                                            onChange={(e) => setFamily(e.target.value)}
                                            required
                                        />
                                        <label>Last Name</label>
                                    </div>

                                    <div className="mb-3">
                                        <label className="form-label text-color">Profile Image</label>
                                        <input
                                            type="file"
                                            className="form-control"
                                            onChange={(e) => setImage(e.target.files[0])}
                                        />
                                    </div>

                                    <div className="form-floating mb-3">
                                        <input
                                            type="email"
                                            className="form-control"
                                            placeholder="Email"
                                            value={email}
                                            onChange={(e) => setEmail(e.target.value)}
                                            required
                                        />
                                        <label>Email</label>
                                    </div>

                                    <div className="form-floating mb-3">
                                        <input
                                            type="tel"
                                            className="form-control"
                                            placeholder="09123456789"
                                            value={phone}
                                            onChange={(e) => setPhone(e.target.value)}
                                            pattern="[0-9]{11}"
                                            required
                                        />
                                        <label>Phone Number</label>
                                    </div>

                                    <div className="form-floating mb-3">
                                        <input
                                            type="password"
                                            className="form-control"
                                            placeholder="Password"
                                            value={password}
                                            onChange={(e) => setPassword(e.target.value)}
                                            minLength="8"
                                            required
                                        />
                                        <label>Password</label>
                                    </div>

                                    {error && <p className="text-danger">{error}</p>}

                                    <button type="submit" className="btn text-color boder w-100" disabled={loading}>
                                        {loading ? 'در حال ثبت...' : 'Register'}
                                    </button>

                                </form>

                                <div className="mt-3">
                                    <p className="text-color">
                                        Already have an account?
                                        <Link to="/login" className="btn text-color boder ms-2">
                                            Login
                                        </Link>
                                    </p>
                                </div>

                            </div>
                        </div>
                    </div>

                    <div className="col-xl-7 col-md-12 d-none d-xl-block">
                        <div className="d-flex align-items-center justify-content-center custom-offset">
                            <div className="item-back boder p-5 rounded-5 login-div w-100">
                                <img
                                    src="/css/IPhone16.jpg"
                                    alt="register"
                                    className="rounded-5 regester-img object-fit-cover w-100"
                                />
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </main>
    );
}

export default Register;
